import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from './prims'

test('@journey:negative @smoke rejects malformed email in contact form', async ({ page }) => {
  await opGoto(page, '/contact')
  await opFill(page, 'Email', 'invalid-email')
  await opFill(page, 'Name', 'John Doe')
  await opFill(page, 'Which service are you interested in', 'Support')
  await opFill(page, 'Message', 'Testing.')
  await opClick(page, 'button', 'Submit')
  await opSeen(page, 'dialog', 'Please enter a valid email address.')
})
